# Longest ORFs plus strand
def orfs_plus(s):
    res=[]
    for f in range(3):
        i=f
        while i<n-2:
            if s[i:i+3]=="ATG":
                j=i
                while j<n-2:
                    if s[j:j+3] in ("TAA","TAG","TGA"): break
                    j+=3
                res.append((i,min(j+3,((n-1-i)//3)*3+i), j-i))
            i+=3
    return res

# simpler: just ORF from first ATG
def longest_orf(s):
    best=None
    for i in range(n-2):
        if s[i:i+3]=="ATG":
            j=i
            while j<n-2 and s[j:j+3] not in ("TAA","TAG","TGA"):
                j+=3
            L=j-i
            if best is None or L>best[2]:
                best=(i,j,L)
    return best

