m=rc(seq)
stops=("TAA","TAG","TGA")

def stop_positions(s):
    d={0:[],1:[],2:[]}
    for f in range(3):
        for i in range(f,len(s)-2,3):
            if s[i:i+3] in stops:
                d[f].append(i)
    return d

