    seq+=line
seq=seq.upper(); n=len(seq)
def rc(s): return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

def find_both(mot):
    out=[]
    for strand,s in (("+",seq),("-",rc(seq))):
        p=0
        while True:
            k=s.find(mot,p)
            if k<0: break
            if strand=="+": out.append((strand,k+1))
            else: out.append((strand,n-k-len(mot)+1))
            p=k+1
    return out

for mot in ["TATAAT","TTGACA","TATAAA","TATAAT","GCTGGTGG","TTATCCACA","GGAGG","TATAAAA","TTGAAA"]:
    print("%-10s"%mot, find_both(mot)[:6])

